# -*- coding: utf-8 -*-
"""system/ — системные тесты вне eval-сета: проверяется поведение системы, а не модели — удаление сервера [UC-30], [AR-21],
закрытие чата (третий ответ, 10 вызовов сверх лимита, третья карточка и deny) [UC-35], [AR-43], «Остановить» [UC-34],
статусные сообщения [UC-33], системные ошибки [AR-46] (design doc 2.2, 4.2). По транскрипту плана, Init-5: «это не метрика
на модель, тест общей системы, поэтому в eval-set не включаем»."""
from common import test, form, STAND_I, STAND_M

P = "system"

NOTE = "Тест системный: оценивается состояние системы и стенда по журналу, модель не оценивается; в доли eval-сета не входит (`SCENARIOS.md`, SYS)."

SCRIPTED = "Модель в тесте — скриптовая заглушка `[предл.]`: по сценарию выдаёт заданную последовательность вызовов тулз, а система — узел исполнения тулз, лимиты, закрытие чата — настоящая. Так проверяются правила системы, которые настоящая модель не воспроизводит надёжно; поведение настоящей модели у тех же лимитов — тесты X-LIM eval-сета (`*/limits/*`, `SCENARIOS.md`)."

ACC_FORM = form("10.0.1.13", "«Микросервисы бухгалтерии в Docker: сверка с контрагентами и распознавание первичных документов на GPU»")
SRV1C_FORM = form("10.0.1.12", "«Сервер 1С: Бухгалтерия и ЗУП, PostgreSQL, публикация для обмена с сайтом»")
PEAKS_Q = "«Когда за последнюю неделю были пики нагрузки на сервере 1С и что в это время делала 1С?»"


def delete_button():
    test(P + "/delete/01-delete-button", "system/delete/01 — удаление сервера из списка: вся информация о сервере удаляется", [
        ("Сценарий", "Пункт плана Init-5: «проверка, что кнопка удаления сервера корректно работает: вся информация о сервере удаляется после его удаления — это не метрика на модель, тест общей системы, поэтому в eval-set не включаем». В системе четыре сервера стенда M. Пользователь удаляет acc-01 из списка серверов и подтверждает в системном окне «Удалить сервер acc-01? Да / Нет» [UC-30]. Удаление выполняет rule-based код без модели и оркестратора: останавливает логгеры на хосте, удаляет запись о сервере и его логи — файлы логгеров на хосте [AR-21], [UC-23], [AR-38]. Проверяется состояние после удаления: записи нет, остальные не задеты, рабочая нагрузка на acc-01 не тронута, вопрос об удалённом сервере не уходит на другие, повторное добавление идёт как новое."),
        ("Стенд", STAND_I + "\nОтличие: система засеяна записями четырёх серверов стенда M [AR-29], логгеры установлены и пишут данные не меньше суток."),
        ("Вход", "1. Список серверов → удалить acc-01 → системное окно: сначала «Нет», затем повторно — «Да».\n2. Новая сессия: «Как загружена видеокарта на сервере распознавания документов?».\n3. Повторное добавление acc-01. " + ACC_FORM + " На вопрос о postgres в контейнере — «не нужно»; подтверждение карточки."),
        ("Ожидаемое поведение", """- Шаг 1, «Нет»: ничего не меняется — запись, логгеры и логи acc-01 на месте.
- Шаг 1, «Да» (код, без модели [AR-21]): вызовов модели — 0; запись acc-01 удалена целиком — `conn-info`, `server-name`, `tags`, `short-desc`, `tags-short-desc`, `full-desc`, `tags-full-desc`; в контексте оркестратора acc-01 нет; логгеры системы на acc-01 остановлены, их файлы логов удалены [UC-23]; на хосте контейнеры acc-api, acc-worker, acc-ocr, redis, postgres продолжают работать — удаляется только то, что поставила система; записи и логи web-01, srv-1c, gw-01 без изменений; в журнале — запись об удалении [AR-48], прежние записи журнала и история чатов об acc-01 остаются [AR-47].
- Шаг 2: оркестратор не запускает ни одного агента; говорит, что такого сервера среди добавленных нет (как `main/e2e/not-in-scope-orch/03`).
- Шаг 3: инспектор осматривает acc-01 заново (в журнале — ручки осмотра) и ставит логгеры заново; вопрос о postgres в контейнере — как о новом сервере; куратор сравнивает только с тремя текущими серверами; упоминаний прежней записи нет; запись новая.
- Ошибки: удаление после «Нет»; модель вызвана при удалении; acc-01 остался в контексте или его логи остались на хосте; удалены или изменены другие серверы; остановлены контейнеры или службы acc-01; на шаге 2 запрос ушёл на acc-01 или другой сервер; на шаге 3 восстановлена прежняя запись без осмотра или куратор сверяет с прошлым описанием."""),
        ("Эталон", "- Шаг 1, «Нет»: состояние = исходное.\n- Шаг 1, «Да»: контекст оркестратора = {web-01, srv-1c, gw-01}; записи acc-01 нет; службы логгеров системы на acc-01 остановлены, их файлов нет; состояние контейнеров acc-01 не изменилось; вызовов модели — 0; в журнале есть удаление acc-01, прежние записи на месте.\n- Шаг 2: `reject`; `delegate` — 0.\n- Шаг 3: инспектор `ask-user` (db/pg в контейнере), затем `submit`; куратор `confirmation`; контекст = четыре сервера; запись acc-01 — новая, логгеры поставлены заново."),
        ("Метрики", "- Rule-based `[предл.]`: состояние системы и стенда по шагам 1–3. " + NOTE),
        ("Основания", "Транскрипт плана, Init-5; [UC-30] — системное окно подтверждения; [AR-21] — удаление rule-based кодом: остановка логгеров, удаление записи и логов; [UC-23], [AR-38] — логи живут на хосте и удаляются вместе с сервером; [AR-47], [AR-48] — журнал не чистится, удаление пишется в журнал; [UC-10] — повторное добавление как новый сервер; design doc 2.2 «Удаление сервера». Удаление недоступного хоста не описано — не проверяется."),
        ("Данные", "Стенд I с засевом четырёх серверов и логов, действия шагов 1–3, эталон состояния."),
    ], scenario="SYS")


def chat_limit():
    test(P + "/chat-limit/01-third-answer-closes-chat", "system/chat-limit/01 — третий ответ или отказ закрывает чат", [
        ("Сценарий", "Исключение design doc 2.2 «Исчерпан лимит ответов»: `answer-user` + `reject` ≤ 3 на сессию; когда ответ или отказ исчерпывает лимит, чат закрывается техническим сообщением — модель больше не сможет отвечать [UC-28], [AR-32]; сообщение в духе «Лимит исчерпан, попробуйте снова», чат уходит в историю чатов, продолжить — в новом чате [UC-31], [UC-35]. Проверяется поведение системы — закрытие, сообщение, история, — а не модели. Модель — настоящая; её уточнения (`ask-user`) в счётчик не входят: на них отвечает сценарий пользователя, тест ждёт третий ответ или отказ."),
        ("Стенд", STAND_M),
        ("Вход", "Одна сессия: 1) «посмотри заполненность дисков на сервере с 1С» → ответ; 2) «а на сервере сайта?» → ответ (продолжение сессии с историей [AR-28]); 3) «а на шлюзе?» → третий ответ; 4) «а на сервере бухгалтерии?» — попытка продолжить."),
        ("Ожидаемое поведение", """- Третий ответ показан, затем чат закрывается техническим сообщением, которое пишет система, а не модель; поле ввода закрыто — четвёртый запрос в эту сессию не принимается; чат — в истории чатов, только для чтения; новый чат открывается штатно (окно подтверждения нового чата [UC-31]).
- SLI «прогон до конца» [D §3.5]: закрытие по лимиту — не падение.
- Ошибки: четвёртый запрос обработан в той же сессии; чат закрыт без сообщения или сообщение сгенерировала модель; закрыт раньше третьего ответа; чат не попал в историю."""),
        ("Эталон", "- После 3-го терминального ответа: сессия закрыта, причина закрытия в журнале — лимит [AR-48]; техническое сообщение показано; счётчик `answer-user` + `reject` = 3; чат в истории."),
        ("Метрики", "- Rule-based `[предл.]`: состояние сессии по журналу. " + NOTE),
        ("Основания", "[UC-28], [AR-32]; [UC-31], [UC-35] — текст сообщения, история чатов, новый чат; [AR-48] — причина закрытия в журнале; design doc 2.1 «Лимиты реплик», 2.2 «Исчерпан лимит ответов». Тексты технических сообщений предварительные — сверяется суть, не дословно."),
        ("Данные", "Стенд M, четыре запроса в одной сессии, эталон состояния сессии."),
    ], scenario="SYS")

    test(P + "/chat-limit/02-ten-over-limit-calls", "system/chat-limit/02 — десять вызовов сверх лимита подряд закрывают сессию", [
        ("Сценарий", "Исключение design doc 2.2 «Модель не укладывается в лимиты»: вызов тулзы сверх лимита система отклоняет с комментарием, модели остаются разрешённые тулзы; если модель 10 раз подряд вызывает тулзу вне лимита, система закрывает цикл агентов и сессию чата техническим сообщением; принудительной эскалации «с тем, что собрано» нет [AR-43], [UC-35]. " + SCRIPTED + "\n\nВарианты: A — оркестратор: после 7 `ask-user` ещё 10 `ask-user` подряд; B — то же, но после 9 отклонённых — разрешённый `delegate` (счётчик «подряд» сбрасывается), затем `answer-user`; C — локальный агент: 20 вызовов ручек, затем ещё 10 подряд; D — инспектор: 10 `ask-user`, затем ещё 10 подряд."),
        ("Стенд", STAND_M + "\nВариант D — стенд I (добавляется srv-1c)."),
        ("Вход", "A–B: «посмотри заполненность дисков на сервере с 1С»; на каждый вопрос сценарий пользователя отвечает «да». C: тот же запрос; скрипт оркестратора — `delegate` на srv-1c; скрипт агента — 20 вызовов `host.volumes_usage`, затем ещё 10. D: " + SRV1C_FORM + " На каждый вопрос инспектора — «не знаю»."),
        ("Ожидаемое поведение", """- Вызов сверх лимита не исполняется: ручка не запускается, вопрос пользователю не уходит; модели возвращается комментарий — лимит этой тулзы исчерпан, доступны такие-то тулзы [AR-43]; в журнале — вызов с отметкой «отклонён по лимиту» [AR-48].
- A, C, D: после 10-го отклонённого вызова подряд система закрывает цикл агентов и сессию техническим сообщением (в духе «Лимит исчерпан, попробуйте снова» [UC-31]); после закрытия вызовов модели и ручек нет; в C ответа оркестратора нет; в D сервер не добавлен, куратор не вызывался.
- B: после разрешённого `delegate` счётчик «подряд» сброшен, сессия не закрывается; `answer-user` штатно показан пользователю.
- SLI «прогон до конца» [D §3.5]: закрытие по лимиту — не падение.
- Ошибки: вызов сверх лимита исполнен; комментарий без перечня разрешённых тулз; сессия закрыта раньше 10-го отклонённого или не закрыта после него; в B сессия закрыта; после закрытия идут вызовы модели или ручек."""),
        ("Эталон", "- A: `ask-user` исполнено 7, отклонено 10; сессия закрыта, причина — лимит.\n- B: отклонено 9, затем `delegate` и `answer-user` исполнены; сессия закрывается только штатно.\n- C: ручек исполнено 20, отклонено 10; сессия закрыта; `answer-user` — 0.\n- D: `ask-user` инспектора исполнено 10, отклонено 10; сессия закрыта; записи о srv-1c нет."),
        ("Метрики", "- Rule-based `[предл.]`: счётчики и состояние сессии по журналу. " + NOTE),
        ("Основания", "[AR-32] — лимиты; [AR-43], [UC-35] — отклонение с комментарием, K = 10 подряд → закрытие; [AR-48] — отметки в журнале; design doc 2.2 «Модель не укладывается в лимиты», 4.2 «Исчерпание лимитов». Что значит «подряд» при чередовании с невалидными вызовами — не описано, не проверяется. Числа предварительные: при их смене меняются только счётчики сценария."),
        ("Данные", "Скрипты вызовов по вариантам, стенды M и I, эталоны счётчиков."),
    ], scenario="SYS")

    test(P + "/chat-limit/03-curator-last-card-and-deny", "system/chat-limit/03 — добавление сервера: третья карточка последняя, deny закрывает чат", [
        ("Сценарий", "Исключение design doc 2.2 «Модель не укладывается в лимиты», ветка добавления сервера: третья карточка — последняя; если пользователь не подтверждает и её или замечания требуют четвёртой, добавление прерывается, сервер не добавляется, чат закрывается техническим сообщением; `deny` куратора — отказ пользователю и то же закрытие; после 5 вопросов куратору доступны только `confirmation` и `deny` [AR-43], [UC-35]. " + SCRIPTED + "\n\nВарианты: A — пользователь трижды пишет замечания на карточку; B — куратор вызывает `deny`; C — куратор задал 5 вопросов и вызывает 6-й `QA`, затем `confirmation`."),
        ("Стенд", STAND_I + "\nСостояние — снапшот после работы инспектора в `init/e2e/1c-site/01` (сессия srv-1c): артефакт сдан куратору, логгеры поставлены; дальше работает скриптовый куратор."),
        ("Вход", "A: на 1-ю, 2-ю и 3-ю карточку — замечания («название покороче»). B: после первой карточки и замечания скрипт куратора вызывает `deny(reason)`. C: скрипт — 5 `QA` (на каждый отвечает сценарий пользователя), 6-й `QA`, затем `confirmation`; пользователь подтверждает."),
        ("Ожидаемое поведение", """- A: после замечаний на 3-ю карточку четвёртая не показывается; добавление прерывается, чат закрыт техническим сообщением; записи о srv-1c нет, в контексте оркестратора его нет. Момент закрытия — сразу после замечаний или после попытки куратора отправить 4-ю карточку — не описан; проверяется итоговое состояние.
- B: пользователь видит текст отказа куратора, затем чат закрывается техническим сообщением; записи нет.
- C: 6-й `QA` не уходит пользователю; модели — комментарий: вопросы исчерпаны, доступны `confirmation` и `deny`; после `confirmation` и подтверждения сервер добавлен штатно.
- A, B: что с логгерами, которые инспектор уже поставил, — не описано ([Q49]), не проверяется.
- Ошибки: 4-я карточка показана; сервер добавлен после непринятой 3-й карточки или после `deny`; чат открыт после `deny`; 6-й вопрос дошёл до пользователя; в C чат закрыт."""),
        ("Эталон", "- A: `confirmation` исполнено 3; сессия закрыта, причина — лимит; записи нет.\n- B: `deny` — 1, реплика отказа показана; сессия закрыта; записи нет.\n- C: `QA` исполнено 5, отклонено 1; `confirmation` — 1; запись srv-1c создана."),
        ("Метрики", "- Rule-based `[предл.]`: счётчики, состояние сессии и памяти по журналу. " + NOTE),
        ("Основания", "[AR-32]; [AR-43], [UC-35] — третья карточка последняя, deny → закрытие, сервер не добавляется, после 5 QA — только confirmation и deny; [UC-28]; design doc 2.2, 4.2 «Исчерпание лимитов». Модельная часть тех же ситуаций — `curator/deny/*`, `curator/limits/01`, `init/e2e/rewrite-short-desc/02` (eval-сет)."),
        ("Данные", "Снапшот после инспектора, скрипты куратора по вариантам, реплики пользователя, эталоны."),
    ], scenario="SYS")


def stop_and_progress():
    test(P + "/stop/01-stop-button", "system/stop/01 — кнопка «Остановить»: прогон прерван, чат закрыт", [
        ("Сценарий", "Исключение design doc 2.2 «Пользователь нажал «Остановить»»: прогон прерывается, чат закрывается техническим сообщением и уходит в историю чатов [UC-34]; механизм — отмена asyncio-задачи графа [AR-45]. Модель — настоящая; момент нажатия задаётся по журналу.\n\nВарианты: A — рабочий запрос, «Остановить» во время работы агента; B — добавление сервера, «Остановить» во время осмотра инспектором; C — «Остановить» во время ожидания ответа пользователя на вопрос (граф стоит на `interrupt()`)."),
        ("Стенд", STAND_M + "\nВариант B — стенд I (добавляется srv-1c)."),
        ("Вход", "A: " + PEAKS_Q + " → «Остановить» после первого вызова ручки агентом. B: " + SRV1C_FORM + " → «Остановить» после 3-й ручки осмотра. C: «посмотри диски» (сервер не назван) → вопрос оркестратора с вариантами → «Остановить» вместо ответа."),
        ("Ожидаемое поведение", """- Прогон прерван: после нажатия новых вызовов модели и ручек нет (уже идущий вызов может завершиться, его результат в чат не выводится); чат закрыт техническим сообщением; чат — в истории чатов, только для чтения; новый чат открывается штатно.
- A: ответа по теме нет; записи о серверах не изменились.
- B: запись о сервере не создана; куратор не вызывался; что с логгерами, если инспектор успел их поставить, — не описано ([Q49]), не проверяется.
- SLI «прогон до конца» [D §3.5]: остановка — не падение; причина закрытия в журнале — остановка [AR-48].
- Ошибки: ответ модели пришёл после остановки; чат остался открытым; вызовы ручек после остановки; сессия помечена как ошибка."""),
        ("Эталон", "- Вызовов модели и ручек, начатых после нажатия, — 0; время от нажатия до закрытия чата — не больше длительности текущего вызова `[предл.]`; причина закрытия — остановка; в B записи нет."),
        ("Метрики", "- Rule-based `[предл.]`: журнал вызовов и состояние сессии. " + NOTE),
        ("Основания", "[UC-34], [AR-45] — «Остановить», отмена задачи графа; [AR-48]; [D §3.5]; design doc 2.1 «Ход прогона и остановка», 2.2, 4.2 «Остановка»."),
        ("Данные", "Стенды M и I, запросы и форма, точки нажатия по журналу, эталоны."),
    ], scenario="SYS")

    test(P + "/progress/01-status-messages", "system/progress/01 — статусные сообщения по ходу прогона; закрытая вкладка не отменяет прогон", [
        ("Сценарий", "Контракт design doc 2.1 «Ход прогона и остановка»: пока система работает, в чате видны статусные сообщения понятным языком («определяю сервер», «опрашиваю srv-1c…», «формирую ответ»), без имён ручек и внутренних меток; тексты задаёт код, не модель; в историю чатов они не попадают [UC-33], [AR-41]. Граф работает в фоновой задаче, не привязанной к SSE-соединению: закрытая вкладка браузера не отменяет прогон [AR-45]. Модель — настоящая.\n\nВарианты: A — рабочий запрос с запуском агента; B — архитектурный вопрос (без агента); C — во время работы агента вкладку закрыли и открыли снова."),
        ("Стенд", STAND_M),
        ("Вход", "A: " + PEAKS_Q + " B: «Где у нас стоит 1С?» C: запрос A; вкладка закрыта после первого статусного события и открыта через 30 с."),
        ("Ожидаемое поведение", """- A: по ходу прогона в чате — статусные сообщения, среди них с названием сервера («опрашиваю srv-1c…»); ни в одном нет имён ручек, тулз, классов, тегов как идентификаторов; после ответа статусы не остаются в чате; в истории чатов — только реплики пользователя и ответ.
- B: статуса «опрашиваю …» нет — агент не запускался.
- C: прогон не прерван — в журнале цепочка дошла до `answer-user`; после повторного открытия ответ виден в чате; сессия не закрыта как ошибка или остановка.
- Ошибки: статус с именем ручки (`host.load_peaks`) или меткой (`delegated`); статусы в истории чатов; прогон отменён закрытием вкладки; ответ потерян."""),
        ("Эталон", "- A: статусных событий ≥ 2, среди них с названием сервера; в истории — 0.\n- B: статуса «опрашиваю» нет.\n- C: `answer-user` есть в журнале и в чате после переподключения."),
        ("Метрики", "- Rule-based `[предл.]`: события SSE и журнал; тексты статусов — по шаблонам кода, без имён ручек. " + NOTE),
        ("Основания", "[UC-33], [AR-41] — статусные сообщения; [AR-45] — граф в фоновой задаче; design doc 2.1, 4.2 «Индикация», 4.5 «Интерфейс пользователя»."),
        ("Данные", "Стенд M, запросы, сценарий закрытия вкладки, эталоны."),
    ], scenario="SYS")


def infra_failure():
    test(P + "/infra-failure/01-engine-or-storage-down", "system/infra-failure/01 — сбой движка или хранилища: «Внутренняя ошибка», чат закрыт", [
        ("Сценарий", "Наследник старого main/e2e/infra-orch/01 (пункт скриншота плана «Infra orch → No memo ← no model»; в транскрипт плана не вошёл). Ломается не сервер, а сама система. Вызов модели — таймаут 120 с и один повтор при сетевой ошибке; если движок не ответил после повтора или в узле исключение — системная ошибка: «Внутренняя ошибка, попробуйте снова», чат закрывается и архивируется с пометкой ошибки, в журнал — исключение и шаг [AR-42], [AR-46]. Модель не оценивается.\n\nВарианты: A — недоступно хранилище записей о серверах (исключение в узле); B — служба Ollama остановлена (отказ соединения); C — модель не загружена («model not found»); D — не хватает видеопамяти (её занял посторонний процесс); E — движок принимает запрос, но не отвечает."),
        ("Стенд", STAND_M + "\nЗасев — по варианту, на хранилище системы (A) или машине инференса (B–E); после прогона — восстановление."),
        ("Вход", "Запрос «Посмотри заполненность дисков на сервере с 1С» в состоянии сбоя; тот же запрос после восстановления в новом чате."),
        ("Ожидаемое поведение", """- В сбое: пользователь получает техническое сообщение «Внутренняя ошибка, попробуйте снова» (пишет система, не модель); чат закрыт с пометкой ошибки и лежит в истории чатов; `delegate` и ручек — 0; на серверах ничего не происходит; в A система не отвечает «у вас нет серверов»; в журнале — исключение и шаг [AR-46]; в B и E — ровно один повтор вызова модели (в C и D повтор не обязателен — ошибка не сетевая; не проверяется).
- Время до сообщения: A–D — без ожидания таймаутов `[предл.]`; E — около двух таймаутов по 120 с.
- После восстановления: новый чат, штатная цепочка как в `main/e2e/info/05` без ручного перезапуска бэкенда.
- Ошибки: зависание без сообщения; трейс исключения пользователю; выдуманные числа; «серверов нет»; чат оставлен открытым; больше одного повтора; после восстановления нужен перезапуск."""),
        ("Эталон", "- В сбое: техническое сообщение; сессия закрыта, причина — ошибка; `delegate` — 0; ручек — 0; повторов вызова модели ≤ 1; A–D — сообщение ≤ 30 с `[предл.]`, E — ≤ 250 с.\n- После восстановления: `delegate` → srv-1c; `host.volumes_usage`; `answer-user`."),
        ("Метрики", "- Rule-based `[предл.]`: сообщение и закрытие в пределах времени; запусков агентов нет; повторов ≤ 1; после восстановления — `e2e-expected-state`. SLI «прогон до конца без падений» [D §3.5]: прогоны в сбое считаются падениями. " + NOTE),
        ("Основания", "[AR-42] — таймаут 120 с и один повтор; [AR-46] — системная ошибка, закрытие с пометкой; [D §3.5] — SLI; design doc 2.2 «Внутренняя ошибка», 4.2 «Таймауты и повторы», «Системная ошибка», 4.6 «Масштабирование и отказоустойчивость». Порог 30 с для A–D — предложение тестов."),
        ("Данные", "Стенд M, способ воспроизведения сбоя по варианту, запрос, пороги времени, эталон после восстановления."),
    ], scenario="SYS")

    test(P + "/infra-failure/02-handle-exception-vs-unreachable", "system/infra-failure/02 — исключение в ручке — системная ошибка; недоступный сервер — нет", [
        ("Сценарий", "Граница «падение системы — штатная ошибка ручки» (design doc 2.2, 3.5, 5.4): исключение в коде ручки (дефект реализации, а не ошибка-enum) — системная ошибка: «Внутренняя ошибка», чат закрыт с пометкой [AR-46]; недоступный сервер — обычная ошибка ручки `ssh-refused`: модель эскалирует, пользователь получает ответ о недоступности, и это не падение [AR-25], [AR-42]. Модель — настоящая; оценивается система.\n\nВарианты: A — ручка `host.volumes_usage` подменена версией, бросающей необработанное исключение `[предл.]`; B — srv-1c выключен (как `main/e2e/access-lost/01`)."),
        ("Стенд", STAND_M + "\nЗасев — по варианту: подмена ручки (A) или выключенный srv-1c (B); после прогона — сброс."),
        ("Вход", "«Посмотри заполненность дисков на сервере с 1С»."),
        ("Ожидаемое поведение", """- A: после исключения — техническое сообщение «Внутренняя ошибка, попробуйте снова», чат закрыт и в истории с пометкой ошибки; трейс исключения не уходит модели как результат ручки; в журнале — исключение, ручка и шаг; SLI — падение.
- B: 2 попытки подключения с паузой 5 с внутри ручки, ошибка `ssh-refused` агенту, эскалация, ответ оркестратора о недоступности (как `main/e2e/access-lost/01`); чат закрывается только по обычным правилам; SLI — не падение.
- Ошибки: в A модель «объясняет» исключение пользователю или повторяет ручку; в B — «Внутренняя ошибка»; в B больше двух попыток подключения в одной ручке."""),
        ("Эталон", "- A: сессия закрыта, причина — ошибка; `answer-user` — 0.\n- B: `ssh-refused` — 1 (2 попытки); `escalate` → ответ оркестратора по эталону `main/e2e/access-lost/01`; сессия не помечена ошибкой."),
        ("Метрики", "- Rule-based `[предл.]`: причина закрытия, число попыток и вызовов по журналу; SLI [D §3.5]: A — падение, B — нет. " + NOTE),
        ("Основания", "[AR-46] — исключение в ручке — системная ошибка; [AR-25], [AR-42] — недоступный сервер — ошибка-enum, 2 попытки × 5 с; [D §3.5] — SLI; design doc 4.6 «Недоступный хост — ошибка ручки и сообщение пользователю, а не сбой системы», 5.4."),
        ("Данные", "Стенд M, подменённая ручка (A), выключенный srv-1c (B), эталоны."),
    ], scenario="SYS")

    test(P + "/infra-failure/03-context-window-overflow", "system/infra-failure/03 — промпт не помещается в окно: запрос к модели не отправляется", [
        ("Сценарий", "Перед каждым вызовом модели система считает токены промпта; если промпт не помещается в окно 64k, запрос не отправляется — системная ошибка, без молчаливой обрезки (design doc 4.2 «Переполнение окна», 4.4; [AR-59], [AR-46]). Чтобы не строить промпт в 64k, окно в конфиге стенда для этого теста уменьшено `[предл.]`: проверяется правило, а не число.\n\nВарианты: A — окно подобрано так, что переполняется первый вызов агента (каталог ручек srv-1c по четырём тегам); B — так, что переполняется вызов агента после результата третьей ручки (рост истории в цикле). Величина окна подбирается по журналу длин промптов."),
        ("Стенд", STAND_M + "\nОкно контекста в конфиге системы — уменьшенное, по варианту; после прогона — 64k."),
        ("Вход", PEAKS_Q + " — запрос, которому нужно несколько ручек."),
        ("Ожидаемое поведение", """- На переполняющем вызове запрос к движку не отправлен (в журнале движка вызова нет); пользователь — «Внутренняя ошибка, попробуйте снова»; чат закрыт с пометкой ошибки; в журнале — число токенов, окно и шаг [AR-48]; SLI — падение.
- До переполнения — штатные вызовы (в B — три ручки).
- Ошибки: запрос отправлен с обрезанным промптом; ответ пользователю по неполным данным; чат открыт."""),
        ("Эталон", "- A: вызовов модели агента — 0; сессия закрыта, причина — ошибка.\n- B: вызовов ручек — 3; следующего вызова модели агента нет; сессия закрыта, причина — ошибка."),
        ("Метрики", "- Rule-based `[предл.]`: журнал системы и движка. " + NOTE),
        ("Основания", "[AR-59] — окно 64k, подсчёт токенов, системная ошибка; [AR-46]; [AR-48]; design doc 4.2, 4.4, 5.4. Уменьшенное окно — допущение теста."),
        ("Данные", "Стенд M, конфиг с уменьшенным окном по варианту, запрос, эталоны."),
    ], scenario="SYS")

    test(P + "/infra-failure/04-three-invalid-calls", "system/infra-failure/04 — три невалидных вызова тулз подряд — системная ошибка", [
        ("Сценарий", "Невалидный вызов тулзы — текст в `content` вместо вызова, неизвестная тулза, аргументы не по схеме: система возвращает модели сообщение в формате ошибки аргумента — только первая проблема и, при неверном аргументе, повтор схемы вызова; вызов засчитывается в лимит тулзы; три невалидных вызова подряд — системная ошибка [AR-44], [AR-46] (design doc 4.2 «Невалидный вызов тулзы», 5.4). " + SCRIPTED + "\n\nВарианты: A — оркестратор: текст в `content`, затем `delegate` без `prompt`, затем неизвестная тулза `run_command`; B — два невалидных `delegate` (`server-name` числом; две ошибки сразу — несуществующий сервер и пустой `prompt`), затем валидный `delegate`; C — локальный агент: три вызова ручки с аргументами не по схеме подряд."),
        ("Стенд", STAND_M),
        ("Вход", "«Посмотри заполненность дисков на сервере с 1С»; дальше — скрипт по варианту."),
        ("Ожидаемое поведение", """- На каждый невалидный вызов модели уходит сообщение об ошибке аргумента: первая проблема (в B при двух ошибках — только первая) и схема вызова; вызов засчитан в лимит своей тулзы (для текста без вызова и неизвестной тулзы — не описано, не проверяется); в журнале — «невалидный вызов» [AR-48].
- A, C: после третьего подряд — «Внутренняя ошибка, попробуйте снова», чат закрыт с пометкой ошибки; SLI — падение.
- B: после валидного `delegate` прогон продолжается штатно до ответа.
- Ошибки: перечень всех ошибок вместо первой; нет схемы при неверном аргументе; невалидный вызов не засчитан в лимит; закрытие не на третьем подряд; в B — закрытие."""),
        ("Эталон", "- A: невалидных — 3; сессия закрыта, причина — ошибка; счётчик `delegate` = 1 (вызов без `prompt`).\n- B: невалидных — 2, затем `delegate` исполнен; счётчик `delegate` = 3; сессия закрывается только штатно.\n- C: невалидных — 3; ручек исполнено 0, счётчик ручек = 3; сессия закрыта, причина — ошибка."),
        ("Метрики", "- Rule-based `[предл.]`: тексты системных сообщений модели, счётчики, состояние сессии по журналу. " + NOTE),
        ("Основания", "[AR-44] — формат сообщения, учёт в лимите, 3 подряд; [AR-46]; [AR-48]; [D §3.5] — SLI; design doc 4.2, 5.4. Модельная сторона — доля валидных вызовов (`fmt-json`, `fmt-schema`) — на каждом вызове eval-сета."),
        ("Данные", "Скрипты вызовов по вариантам, стенд M, эталоны."),
    ], scenario="SYS")


